CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_migrations VALUES(1);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT);
CREATE TABLE IF NOT EXISTS rule_versions(id INTEGER PRIMARY KEY AUTOINCREMENT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,finished_at TEXT,status TEXT NOT NULL,summary TEXT DEFAULT '{}');
CREATE TABLE IF NOT EXISTS pages(version INTEGER,url TEXT,status TEXT,sha256 TEXT,raw_gzip BLOB,error TEXT,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(version,url));
CREATE TABLE IF NOT EXISTS elements(version INTEGER,id TEXT,kind TEXT,name TEXT,level INTEGER,owner TEXT,data TEXT,PRIMARY KEY(version,id));
CREATE INDEX IF NOT EXISTS element_kind ON elements(version,kind,owner,level);
CREATE TABLE IF NOT EXISTS aliases(version INTEGER,alias TEXT,element_id TEXT,PRIMARY KEY(version,alias));
CREATE TABLE IF NOT EXISTS import_log(id INTEGER PRIMARY KEY AUTOINCREMENT,version INTEGER,at TEXT DEFAULT CURRENT_TIMESTAMP,url TEXT,severity TEXT,message TEXT);
CREATE TABLE IF NOT EXISTS characters(id TEXT PRIMARY KEY,name TEXT,data TEXT,revision INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS character_history(character_id TEXT,revision INTEGER,data TEXT,saved_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(character_id,revision));
